const items = $input.all();
const resultados = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  if (!item.binary?.data) {
    throw new Error(`No existe binary.data en el elemento ${i}`);
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const texto = buffer.toString('utf8').replace(/^\uFEFF/, '');

  const lineas = texto.split(/\r?\n/);
  const secciones = [];

  let tituloActual = "Sin encabezado";
  let contenidoActual = [];

  function guardarSeccion() {
    const contenido = contenidoActual.join("\n").trim();

    if (!contenido && tituloActual === "Sin encabezado") {
      return;
    }

    const longitud = (tituloActual + "\n" + contenido).length;

    secciones.push({
      titulo: tituloActual,
      caracteres: longitud,
      supera_500: longitud > 500,
      supera_800: longitud > 800,
      texto: contenido
    });
  }

  for (const linea of lineas) {
    if (/^#{1,6}\s+/.test(linea)) {
      if (tituloActual !== "Sin encabezado" || contenidoActual.length) {
        guardarSeccion();
      }

      tituloActual = linea;
      contenidoActual = [];
    } else {
      contenidoActual.push(linea);
    }
  }

  guardarSeccion();

  resultados.push({
    json: {
      archivo: item.binary.data.fileName,
      chunk_size_actual: 500,
      chunk_overlap_actual: 20,
      total_secciones: secciones.length,
      secciones_mayores_500:
        secciones.filter(s => s.supera_500).length,
      secciones: secciones.map(s => ({
        titulo: s.titulo,
        caracteres: s.caracteres,
        supera_500: s.supera_500,
        supera_800: s.supera_800
      }))
    }
  });
}

return resultados;

const items = $input.all();
const salida = [];

const CHUNK_SIZE = 500;
const OVERLAP = 20;

function dividirTexto(texto, maximo, overlap) {
  const separadores = ["\n\n", "\n", " ", ""];
  const fragmentos = [];

  function segmentar(textoActual, nivel) {
    if (textoActual.length <= maximo) {
      return [textoActual];
    }

    const separador = separadores[nivel];

    if (!separador) {
      const partes = [];
      for (let i = 0; i < textoActual.length; i += maximo) {
        partes.push(textoActual.slice(i, i + maximo));
      }
      return partes;
    }

    const partes = textoActual.split(separador);
    const grupos = [];
    let actual = "";

    for (const parte of partes) {
      const candidato = actual
        ? actual + separador + parte
        : parte;

      if (candidato.length <= maximo) {
        actual = candidato;
      } else {
        if (actual) grupos.push(actual);
        actual = parte;
      }
    }

    if (actual) grupos.push(actual);

    return grupos.flatMap(grupo =>
      grupo.length > maximo
        ? segmentar(grupo, nivel + 1)
        : [grupo]
    );
  }

  const bloques = segmentar(texto, 0);

  for (let i = 0; i < bloques.length; i++) {
    const anterior = fragmentos.length
      ? fragmentos[fragmentos.length - 1].slice(-overlap)
      : "";

    fragmentos.push(anterior + bloques[i]);
  }

  return fragmentos;
}

for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, "data");
  const texto = buffer.toString("utf8").replace(/^\uFEFF/, "");

  const chunks = dividirTexto(texto, CHUNK_SIZE, OVERLAP);

  salida.push({
    json: {
      archivo: items[i].binary.data.fileName,
      total_chunks: chunks.length,
      chunks: chunks.map((contenido, indice) => ({
        indice: indice + 1,
        caracteres: contenido.length,
        contiene_150: /150\s+MINUTOS/i.test(contenido),
        contiene_75: /75\s+MINUTOS/i.test(contenido),
        contenido
      }))
    }
  });
}

return salida;

// PULSO - Chunking estructural Markdown v1.1
// n8n Code - Run Once for All Items
// Corrección: encabezados Markdown seguidos de contenido
// en el mismo bloque, sin perder información.
//
// Uso experimental. NO escribe en Supabase.

const CONFIG = {
  targetSize: 650,
  warningSize: 1200,
  version: "markdown_structural_v1_1"
};

const inputs = $input.all();
const resultados = [];

function normalizar(texto) {
  return texto.replace(/\s+/g, " ").trim();
}

function obtenerEncabezado(texto) {
  // Solo acepta una línea que sea un encabezado.
  const match = texto.match(
    /^(#{1,6})[ \t]+([^\n]+)$/
  );

  if (!match) return null;

  return {
    nivel: match[1].length,
    titulo: match[2].trim(),
    original: texto
  };
}

function esNotaComplementaria(texto) {
  return /^(?:\\?\*+\s*|Nota\s*:|Advertencia\s*:|Precauci[oó]n\s*:)/i
    .test(texto);
}

// Separar líneas de encabezado del contenido
// aunque estén dentro del mismo párrafo Markdown.
function obtenerBloques(texto) {
  const bloques = [];
  const lineas = texto.split("\n");

  let acumulado = [];

  function guardarBloque() {
    const contenido = acumulado.join("\n").trim();

    if (contenido) {
      bloques.push(contenido);
    }

    acumulado = [];
  }

  for (const linea of lineas) {
    const limpia = linea.trim();

    if (!limpia) {
      guardarBloque();
      continue;
    }

    if (obtenerEncabezado(limpia)) {
      guardarBloque();
      bloques.push(limpia);
    } else {
      acumulado.push(linea);
    }
  }

  guardarBloque();

  return bloques;
}

function construirSecciones(bloques) {
  const secciones = [];
  const jerarquia = [];

  let actual = {
    encabezados: [],
    ruta: [],
    bloques: []
  };

  function guardarSeccion() {
    if (
      actual.encabezados.length > 0 ||
      actual.bloques.length > 0
    ) {
      secciones.push(actual);
    }
  }

  for (const bloque of bloques) {
    const encabezado = obtenerEncabezado(bloque);

    if (encabezado !== null) {
      if (actual.bloques.length > 0) {
        guardarSeccion();

        actual = {
          encabezados: [],
          ruta: [],
          bloques: []
        };
      }

      while (
        jerarquia.length > 0 &&
        jerarquia[jerarquia.length - 1].nivel >=
          encabezado.nivel
      ) {
        jerarquia.pop();
      }

      jerarquia.push(encabezado);
      actual.encabezados.push(encabezado.original);
      actual.ruta = jerarquia.map(h => h.titulo);

    } else {
      actual.bloques.push(bloque);
    }
  }

  guardarSeccion();

  return secciones;
}


function construirUnidades(seccion) {
  const unidades = [];

  function agregarUnidad(texto) {
    const limpio = texto.trim();

    if (!limpio) return;

    if (
      esNotaComplementaria(limpio) &&
      unidades.length > 0
    ) {
      unidades[unidades.length - 1] +=
        "\n\n" + limpio;
    } else {
      unidades.push(limpio);
    }
  }

  for (const bloque of seccion.bloques) {
    const lineas = bloque.split("\n");
    let acumulado = "";

    for (const linea of lineas) {
      // Reconocer elementos de listas Markdown.
      // Admite -, *, +, 1. y 1)
      const esElementoLista =
        /^\s*(?:[-*+]\s+|\d+[.)]\s+)/.test(linea);

      if (esElementoLista) {
        // Finalizar el elemento anterior antes
        // de comenzar una nueva recomendación.
        if (acumulado.trim()) {
          agregarUnidad(acumulado);
        }

        acumulado = linea;

      } else {
        // Mantener las líneas continuadas
        // dentro del elemento correspondiente.
        acumulado +=
          (acumulado ? "\n" : "") + linea;
      }
    }

    if (acumulado.trim()) {
      agregarUnidad(acumulado);
    }
  }

  // Asociar encabezados con el primer
  // bloque real de su sección.
  const encabezados =
    seccion.encabezados.join("\n\n");

  if (encabezados) {
    if (unidades.length > 0) {
      unidades[0] =
        encabezados + "\n\n" + unidades[0];
    } else {
      unidades.push(encabezados);
    }
  }

  return unidades;
}

function fragmentarSeccion(seccion, indiceSeccion) {
  const unidades = construirUnidades(seccion);
  const fragmentos = [];

  let acumulado = "";

  function guardar() {
    if (!acumulado) return;

    fragmentos.push({
      pageContent: acumulado,
      metadata: {
        section_index: indiceSeccion,
        section_path: seccion.ruta.join(" > "),
        chunking_version: CONFIG.version
      }
    });

    acumulado = "";
  }

  for (const unidad of unidades) {
    const candidato = acumulado
      ? acumulado + "\n\n" + unidad
      : unidad;

    if (
      acumulado &&
      candidato.length > CONFIG.targetSize
    ) {
      guardar();
      acumulado = unidad;
    } else {
      acumulado = candidato;
    }
  }

  guardar();

  return fragmentos;
}

function esSoloEncabezados(texto) {
  const lineas = texto
    .split("\n")
    .map(l => l.trim())
    .filter(Boolean);

  return lineas.length > 0 &&
    lineas.every(l => obtenerEncabezado(l) !== null);
}

for (
  let inputIndex = 0;
  inputIndex < inputs.length;
  inputIndex++
) {
  const item = inputs[inputIndex];

  if (!item.binary?.data) {
    throw new Error(
      `Item ${inputIndex}: falta binary.data. ` +
      "Conecta el nodo Download file."
    );
  }

  const buffer =
    await this.helpers.getBinaryDataBuffer(
      inputIndex,
      "data"
    );

  const textoOriginal = buffer
    .toString("utf8")
    .replace(/^\uFEFF/, "")
    .replace(/\r\n?/g, "\n")
    .trim();

  const archivo =
    item.binary.data.fileName ||
    item.json?.name ||
    "archivo_sin_nombre.md";

  const bloques = obtenerBloques(textoOriginal);
  const secciones = construirSecciones(bloques);

  const chunks = secciones.flatMap(
    (seccion, i) =>
      fragmentarSeccion(seccion, i + 1)
  );

  const reconstruido = chunks
    .map(c => c.pageContent)
    .join("\n\n");

  const integridadContenido =
    normalizar(reconstruido) ===
    normalizar(textoOriginal);

  const detalle = chunks.map((chunk, i) => {
    const contenido = chunk.pageContent;

    return {
      indice: i + 1,
      caracteres: contenido.length,
      supera_objetivo:
        contenido.length > CONFIG.targetSize,
      supera_advertencia:
        contenido.length > CONFIG.warningSize,
      encabezado_aislado:
        esSoloEncabezados(contenido),
      section_path:
        chunk.metadata.section_path,
      pageContent: contenido,
      metadata: {
        ...chunk.metadata,
        chunk_index: i + 1,
        source_file: archivo
      }
    };
  });

  const largos = detalle.filter(
    c => c.supera_advertencia
  ).length;

  const aislados = detalle.filter(
    c => c.encabezado_aislado
  ).length;

  const advertencias = [];

  if (!integridadContenido) {
    advertencias.push(
      "ERROR: reconstrucción distinta del texto original."
    );
  }

  if (largos > 0) {
    advertencias.push(
      `${largos} chunks superan ${CONFIG.warningSize} caracteres.`
    );
  }

  if (aislados > 0) {
    advertencias.push(
      `${aislados} chunks contienen solamente encabezados.`
    );
  }

  resultados.push({
    json: {
      archivo,
      estrategia: CONFIG.version,
      target_size: CONFIG.targetSize,
      warning_size: CONFIG.warningSize,
      caracteres_originales: textoOriginal.length,
      total_bloques: bloques.length,
      total_secciones: secciones.length,
      total_chunks: detalle.length,
      integridad_contenido: integridadContenido,
      chunks_mayores_650:
        detalle.filter(c => c.supera_objetivo).length,
      chunks_mayores_1200: largos,
      encabezados_aislados: aislados,
      advertencias,
      chunks: detalle
    }
  });
}

return resultados;

// PULSO - Chunking estructural Markdown v1.3
// n8n Code - Run Once for All Items
// Prototipo experimental: NO escribe en Supabase.
//
// Estrategia:
// 1. Respetar secciones y encabezados Markdown.
// 2. Separar elementos de listas.
// 3. Conservar notas complementarias.
// 4. Dividir párrafos extensos por oraciones.
// 5. Auditar la conservación textual.

const CONFIG = {
  targetSize: 650,
  warningSize: 1200,
  version: "markdown_structural_v1_3",
};

const inputs = $input.all();
const resultados = [];

function normalizar(texto) {
  return texto.replace(/\s+/g, " ").trim();
}

function obtenerEncabezado(texto) {
  const m = texto.match(/^(#{1,6})[ \t]+([^\n]+)$/);
  if (!m) return null;

  return {
    nivel: m[1].length,
    titulo: m[2].trim(),
    original: texto,
  };
}

function esNota(texto) {
  return /^(?:\\?\*+\s*|Nota\s*:|Advertencia\s*:|Precauci[oó]n\s*:)/i.test(
    texto,
  );
}

function esElementoLista(linea) {
  return /^\s*(?:[-*+]\s+|\d+[.)]\s+)/.test(linea);
}

// Convierte el documento en bloques.
// Identifica encabezados incluso si están
// inmediatamente seguidos de contenido.
function obtenerBloques(texto) {
  const bloques = [];
  let acumulado = [];

  function guardar() {
    const b = acumulado.join("\n").trim();
    if (b) bloques.push(b);
    acumulado = [];
  }

  for (const linea of texto.split("\n")) {
    if (!linea.trim()) {
      guardar();
      continue;
    }

    if (obtenerEncabezado(linea.trim())) {
      guardar();
      bloques.push(linea.trim());
    } else {
      acumulado.push(linea);
    }
  }

  guardar();
  return bloques;
}

// Construye secciones y registra su jerarquía.
function construirSecciones(bloques) {
  const secciones = [];
  const jerarquia = [];

  let actual = {
    encabezados: [],
    ruta: [],
    bloques: [],
  };

  function guardar() {
    if (actual.encabezados.length || actual.bloques.length) {
      secciones.push(actual);
    }
  }

  for (const bloque of bloques) {
    const h = obtenerEncabezado(bloque);

    if (h) {
      if (actual.bloques.length) {
        guardar();
        actual = {
          encabezados: [],
          ruta: [],
          bloques: [],
        };
      }

      while (
        jerarquia.length &&
        jerarquia[jerarquia.length - 1].nivel >= h.nivel
      ) {
        jerarquia.pop();
      }

      jerarquia.push(h);
      actual.encabezados.push(h.original);
      actual.ruta = jerarquia.map((x) => x.titulo);
    } else {
      actual.bloques.push(bloque);
    }
  }

  guardar();
  return secciones;
}

// Segmentador conservador de oraciones.
// NO divide por cada punto: busca puntuación
// final seguida de una posible oración nueva.
//
// No constituye un analizador lingüístico
// perfecto. Las abreviaturas y referencias
// científicas requieren revisión.
function separarOraciones(texto) {
  const resultado = [];

  const patron = /[.!?](?:["”’)\]]*)\s+(?=[A-ZÁÉÍÓÚÜÑ“‘(])/g;

  let inicio = 0;
  let m;

  while ((m = patron.exec(texto)) !== null) {
    const fin = m.index + m[0].length - (m[0].match(/\s+$/)?.[0].length || 0);

    const parte = texto.slice(inicio, fin).trim();

    if (parte) resultado.push(parte);

    inicio = m.index + m[0].length;
  }

  const resto = texto.slice(inicio).trim();
  if (resto) resultado.push(resto);

  return resultado;
}

// Agrupa oraciones consecutivas hasta
// el objetivo. Conserva su orden.
function dividirParrafoLargo(texto) {
  if (texto.length <= CONFIG.targetSize) {
    return [texto];
  }

  const oraciones = separarOraciones(texto);

  if (oraciones.length <= 1) {
    return [texto];
  }

  const partes = [];
  let actual = "";

  for (const oracion of oraciones) {
    const candidato = actual ? actual + " " + oracion : oracion;

    if (actual && candidato.length > CONFIG.targetSize) {
      partes.push(actual);
      actual = oracion;
    } else {
      actual = candidato;
    }
  }

  if (actual) partes.push(actual);

  // No permitir alteraciones de palabras.
  if (normalizar(partes.join(" ")) !== normalizar(texto)) {
    throw new Error("La segmentación de oraciones alteró el texto.");
  }

  return partes;
}

// Identifica unidades estructurales.
// Los elementos de lista se conservan completos.
// Los párrafos científicos largos pueden dividirse.
function construirUnidades(seccion) {
  const unidades = [];

  function agregar(texto, protegido = false) {
    const limpio = texto.trim();
    if (!limpio) return;

    if (esNota(limpio) && unidades.length) {
      const ultima = unidades[unidades.length - 1];
      ultima.texto += "\n\n" + limpio;
      ultima.protegido = true;
      return;
    }

    if (protegido || limpio.length <= CONFIG.targetSize) {
      unidades.push({
        texto: limpio,
        protegido,
      });
      return;
    }

    for (const parte of dividirParrafoLargo(limpio)) {
      unidades.push({
        texto: parte,
        protegido: false,
      });
    }
  }

  for (const bloque of seccion.bloques) {
    const lineas = bloque.split("\n");

    // Si es una lista, separar por elementos.
    if (lineas.some(esElementoLista)) {
      let acumulado = "";
      let enLista = false;

      function guardarElemento() {
        if (acumulado.trim()) {
          agregar(acumulado, enLista);
        }
        acumulado = "";
      }

      for (const linea of lineas) {
        if (esElementoLista(linea)) {
          guardarElemento();
          acumulado = linea;
          enLista = true;
        } else {
          acumulado += (acumulado ? "\n" : "") + linea;
        }
      }

      guardarElemento();
    } else {
      agregar(bloque);
    }
  }

  const encabezados = seccion.encabezados.join("\n\n");

  if (encabezados) {
    if (unidades.length) {
      unidades[0].texto = encabezados + "\n\n" + unidades[0].texto;
    } else {
      unidades.push({
        texto: encabezados,
        protegido: true,
      });
    }
  }

  return unidades;
}

function crearChunks(seccion, numeroSeccion) {
  const unidades = construirUnidades(seccion);
  const chunks = [];

  let actual = "";

  function guardar() {
    if (!actual) return;

    chunks.push({
      pageContent: actual,
      metadata: {
        section_index: numeroSeccion,
        section_path: seccion.ruta.join(" > "),
        chunking_version: CONFIG.version,
      },
    });

    actual = "";
  }

  for (const unidad of unidades) {
    const candidato = actual ? actual + "\n\n" + unidad.texto : unidad.texto;

    if (actual && candidato.length > CONFIG.targetSize) {
      guardar();
      actual = unidad.texto;
    } else {
      actual = candidato;
    }
  }

  guardar();
  return chunks;
}

function esSoloEncabezados(texto) {
  const lineas = texto
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);

  return lineas.length > 0 && lineas.every((x) => obtenerEncabezado(x));
}

// Procesar cada archivo recibido.
for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];

  if (!item.binary?.data) {
    throw new Error(`Item ${i}: falta binary.data`);
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, "data");

  const textoOriginal = buffer
    .toString("utf8")
    .replace(/^\uFEFF/, "")
    .replace(/\r\n?/g, "\n")
    .trim();

  const archivo =
    item.binary.data.fileName || item.json?.name || "archivo_sin_nombre.md";

  const bloques = obtenerBloques(textoOriginal);
  const secciones = construirSecciones(bloques);

  const chunks = secciones.flatMap((s, indice) => crearChunks(s, indice + 1));

  const textoReconstruido = chunks.map((c) => c.pageContent).join("\n\n");

  const integridad =
    normalizar(textoReconstruido) === normalizar(textoOriginal);

  const detalle = chunks.map((c, indice) => ({
    indice: indice + 1,
    caracteres: c.pageContent.length,
    supera_objetivo: c.pageContent.length > CONFIG.targetSize,
    supera_advertencia: c.pageContent.length > CONFIG.warningSize,
    encabezado_aislado: esSoloEncabezados(c.pageContent),
    section_path: c.metadata.section_path,
    pageContent: c.pageContent,
    metadata: {
      ...c.metadata,
      chunk_index: indice + 1,
      source_file: archivo,
    },
  }));

  const largos = detalle.filter((c) => c.supera_advertencia).length;

  const aislados = detalle.filter((c) => c.encabezado_aislado).length;

  const advertencias = [];

  if (!integridad) {
    advertencias.push("ERROR: el texto reconstruido no coincide.");
  }

  if (largos) {
    advertencias.push(`${largos} chunks superan 1200 caracteres.`);
  }

  if (aislados) {
    advertencias.push(`${aislados} chunks contienen solo encabezados.`);
  }

  resultados.push({
    json: {
      archivo,
      bibliografia: item.json?.bibliografia ?? null,
      estrategia: CONFIG.version,
      target_size: CONFIG.targetSize,
      warning_size: CONFIG.warningSize,
      caracteres_originales: textoOriginal.length,
      total_bloques: bloques.length,
      total_secciones: secciones.length,
      total_chunks: detalle.length,
      integridad_contenido: integridad,
      chunks_mayores_650: detalle.filter((c) => c.supera_objetivo).length,
      chunks_mayores_1200: largos,
      encabezados_aislados: aislados,
      advertencias,
      chunks: detalle,
    },
  });
}

return resultados;

/*
 PULSO - Preparar chunks para embeddings v1.3
 n8n Code: Run Once for All Items

 Convierte documentos auditados en items individuales.
 Conserva y valida metadatos bibliográficos.
 No genera embeddings ni escribe en Supabase.
*/

const entradas = $input.all();
const salida = [];
const claves = new Set();

for (const entrada of entradas) {
  const documento = entrada.json;

  if (documento.integridad_contenido !== true) {
    throw new Error(
      `Integridad no aprobada: ${documento.archivo}`
    );
  }

  if (!Array.isArray(documento.chunks)) {
    throw new Error(
      `El documento ${documento.archivo} no contiene chunks.`
    );
  }

  const archivo = documento.archivo || "";

  const coincidencia = archivo.match(
    /^(SRC-\d+)_NORMALIZADO_RAG_FINAL\.md$/i
  );

  if (!coincidencia) {
    throw new Error(
      `Nombre de archivo no reconocido: ${archivo}`
    );
  }

  const documentId = coincidencia[1].toUpperCase();
  const bibliografia = documento.bibliografia;

  if (!bibliografia || typeof bibliografia !== "object") {
    throw new Error(
      `Falta bibliografía en ${archivo}`
    );
  }

  if (
    bibliografia.document_id !== documentId ||
    bibliografia.source_file !== archivo
  ) {
    throw new Error(
      `Bibliografía incorrecta para ${archivo}. ` +
      `Recibido: ${bibliografia.document_id}`
    );
  }

  const obligatorios = [
    "source",
    "source_url",
    "author",
    "language",
    "document_type",
    "drive_file_id"
  ];

  for (const campo of obligatorios) {
    if (
      typeof bibliografia[campo] !== "string" ||
      !bibliografia[campo].trim()
    ) {
      throw new Error(
        `Falta metadata ${campo} en ${archivo}`
      );
    }
  }

  if (
    documento.total_chunks !== documento.chunks.length
  ) {
    throw new Error(
      `Conteo de chunks inconsistente en ${archivo}`
    );
  }

  if (documento.chunks.length === 0) {
    throw new Error(
      `Documento sin chunks: ${archivo}`
    );
  }

  for (const chunk of documento.chunks) {
    const contenido = chunk.pageContent;

    if (
      typeof contenido !== "string" ||
      !contenido.trim()
    ) {
      throw new Error(
        `Chunk vacío o inválido en ${archivo}`
      );
    }

    if (chunk.supera_advertencia) {
      throw new Error(
        `Chunk ${chunk.indice} supera 1200 caracteres en ${archivo}`
      );
    }

    if (chunk.encabezado_aislado) {
      throw new Error(
        `Encabezado aislado en ${archivo}, chunk ${chunk.indice}`
      );
    }

    if (
      !Number.isInteger(chunk.indice) ||
      chunk.indice < 1 ||
      chunk.indice > documento.total_chunks
    ) {
      throw new Error(
        `Índice de chunk inválido en ${archivo}`
      );
    }

    if (
      chunk.metadata?.source_file !== archivo ||
      chunk.metadata?.chunk_index !== chunk.indice ||
      chunk.metadata?.chunking_version !==
        "markdown_structural_v1_3"
    ) {
      throw new Error(
        `Metadatos estructurales incorrectos en ${archivo}, ` +
        `chunk ${chunk.indice}`
      );
    }

    const clave = `${documentId}:${chunk.indice}`;

    if (claves.has(clave)) {
      throw new Error(
        `Chunk duplicado: ${clave}`
      );
    }

    claves.add(clave);

    const metadata = {
      ...bibliografia,
      document_id: documentId,
      source_file: archivo,
      topics: JSON.stringify(
        bibliografia.topics ?? []
      ),
      section_index: chunk.metadata.section_index,
      section_path: chunk.metadata.section_path,
      chunk_index: chunk.indice,
      chunking_version: "markdown_structural_v1_3"
    };

    salida.push({
      json: {
        pageContent: contenido,
        metadata
      }
    });
  }
}

return salida;

const permitidos = new Set([
  "SRC-02", "SRC-03", "SRC-04",
  "SRC-05", "SRC-06", "SRC-07",
  "SRC-11", "SRC-12", "SRC-13",
  "SRC-14", "SRC-15", "SRC-16",
  "SRC-17", "SRC-18", "SRC-19"
]);

const archivos = $input.all();

const filtrados = archivos.filter(item => {
  const nombre = item.json.name ?? "";

  const match = nombre.match(
    /^(SRC-\d+)_NORMALIZADO_RAG_FINAL\.md$/i
  );

  return match && permitidos.has(match[1].toUpperCase());
});

const encontrados = filtrados.map(
  item => item.json.name.match(/^SRC-\d+/i)[0].toUpperCase()
);

const duplicados = encontrados.filter(
  (id, i) => encontrados.indexOf(id) !== i
);

const faltantes = [...permitidos].filter(
  id => !encontrados.includes(id)
);

if (
  filtrados.length !== 15 ||
  duplicados.length > 0 ||
  faltantes.length > 0
) {
  throw new Error(
    `Corpus incompleto o duplicado. ` +
    `Encontrados: ${filtrados.length}. ` +
    `Faltantes: ${faltantes.join(", ") || "ninguno"}. ` +
    `Duplicados: ${duplicados.join(", ") || "ninguno"}.`
  );
}

return filtrados;

const items = $input.all();
const documentos = items.map(item => item.json);

const esperados = [
  "SRC-02", "SRC-03", "SRC-04", "SRC-05",
  "SRC-06", "SRC-07", "SRC-11", "SRC-12",
  "SRC-13", "SRC-14", "SRC-15", "SRC-16",
  "SRC-17", "SRC-18", "SRC-19"
];

const reporte = documentos.map(doc => {
  const chunks = doc.chunks ?? [];
  const match = (doc.archivo ?? "").match(/^SRC-\d+/i);
  const documentId = match ? match[0].toUpperCase() : null;

  const indices = chunks.map(c => c.indice);
  const duplicadosIndice = indices.length - new Set(indices).size;

  const vacios = chunks.filter(
    c => !c.pageContent || !c.pageContent.trim()
  ).length;

  const metadatosInvalidos = chunks.filter(c =>
    !c.metadata?.section_path ||
    c.metadata?.chunk_index !== c.indice ||
    c.metadata?.chunking_version !== "markdown_structural_v1_3" ||
    c.metadata?.source_file !== doc.archivo
  ).length;

  const problemas = [];

  if (!doc.integridad_contenido)
    problemas.push("Integridad textual incorrecta");

  if (vacios)
    problemas.push(`${vacios} chunks vacíos`);

  if (doc.chunks_mayores_1200)
    problemas.push(`${doc.chunks_mayores_1200} chunks >1200`);

  if (doc.encabezados_aislados)
    problemas.push(`${doc.encabezados_aislados} encabezados aislados`);

  if (duplicadosIndice)
    problemas.push(`${duplicadosIndice} índices duplicados`);

  if (metadatosInvalidos)
    problemas.push(`${metadatosInvalidos} metadatos inválidos`);

  if (chunks.length !== doc.total_chunks)
    problemas.push("Recuento de chunks inconsistente");

  return {
    document_id: documentId,
    archivo: doc.archivo,
    total_chunks: chunks.length,
    caracteres_originales: doc.caracteres_originales,
    integridad_contenido: doc.integridad_contenido,
    chunks_mayores_650: doc.chunks_mayores_650 ?? 0,
    chunks_mayores_1200: doc.chunks_mayores_1200 ?? 0,
    encabezados_aislados: doc.encabezados_aislados ?? 0,
    chunks_vacios: vacios,
    metadatos_invalidos: metadatosInvalidos,
    problemas,
    estado: problemas.length ? "REVISAR" : "OK"
  };
});

const ids = reporte.map(r => r.document_id);
const faltantes = esperados.filter(id => !ids.includes(id));

const repetidos = ids.filter(
  (id, indice) => ids.indexOf(id) !== indice
);

const totalChunks = reporte.reduce(
  (suma, doc) => suma + doc.total_chunks, 0
);

const documentosConProblemas = reporte.filter(
  doc => doc.estado !== "OK"
).length;

const corpusValido =
  reporte.length === 15 &&
  faltantes.length === 0 &&
  repetidos.length === 0 &&
  documentosConProblemas === 0;

return [{
  json: {
    auditoria_version: "PULSO_v1_3",
    total_documentos: reporte.length,
    total_chunks: totalChunks,
    documentos_ok: reporte.length - documentosConProblemas,
    documentos_revisar: documentosConProblemas,
    documentos_faltantes: faltantes,
    ids_repetidos: [...new Set(repetidos)],
    corpus_aprobado: corpusValido,
    detalle_documentos: reporte
  }
}];

const documentos = $input.all();

const encontrados = [];

for (const item of documentos) {
  const doc = item.json;

  if (doc.archivo !== "SRC-07_NORMALIZADO_RAG_FINAL.md") {
    continue;
  }

  for (const chunk of doc.chunks ?? []) {
    if (chunk.encabezado_aislado) {
      encontrados.push({
        json: {
          archivo: doc.archivo,
          chunk_index: chunk.indice,
          section_path: chunk.section_path,
          caracteres: chunk.caracteres,
          pageContent: chunk.pageContent,
          metadata: chunk.metadata
        }
      });
    }
  }
}

return encontrados;

const items = $input.all();

const chunk = items.find(
  item =>
    item.json.metadata?.document_id === "SRC-07" &&
    item.json.metadata?.chunk_index === 1
);

if (!chunk) {
  throw new Error("No se encontró SRC-07, chunk 1");
}

return [chunk];
